const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
const CADENCE = [1, 3, 7];
return $input.all().map(({json}) => {
 const days = daysSince(json.first_contact);
 const due = !json.replied && json.touches < CADENCE.length && days >= CADENCE[json.touches];
 const reason = json.replied ? 'lead replied, sequence stopped' : json.touches >= CADENCE.length ? 'sequence finished' : due ? `day ${CADENCE[json.touches]} follow-up due` : 'next step not due yet';
 return {json: {...json, days_since_first_contact: days, step: json.touches + 1, needs_action: due, reason}};
});

const TEXT = [
 j => `thanks for your interest in a ${j.interest}. I have two listings that match. Would you like the details or a viewing this week?`,
 j => `a new ${j.interest} just came up and I thought of you. Shall I send the photos?`,
 j => `I do not want to crowd your inbox, so this is my last note for now. If the ${j.interest} search is still on, reply any time and I will pick it up.`
];
return $input.all().map(({json}) => {
 const first = json.name.split(' ')[0];
 const message = `Hi ${first}, ${TEXT[json.step - 1](json)} This message was prepared by an automated assistant.`;
 return {json: {...json, channel:'email', to: json.email, subject:`Your search: ${json.interest}`, message, approval:'auto_send'}};
});
